// C[128][128] int32, output matrix at fixed address to avoid tohost conflict
#define C_BASE_ADDR 0x80020000UL
static int32_t (*c)[128] = (int32_t (*)[128])C_BASE_ADDR;

// Reference: compute C_ref = A * B^T on CPU
static int32_t c_ref[128][128];
static void compute_reference(void) {
    for (int i = 0; i < 128; i++)
        for (int j = 0; j < 128; j++) {
            int32_t sum = 0;
            for (int k = 0; k < 128; k++)
                sum += (int32_t)a[i][k] * (int32_t)b[j][k];
            c_ref[i][j] = sum;
        }
}

static int verify_result(void) {
    int errors = 0;
    for (int i = 0; i < 128; i++)
        for (int j = 0; j < 128; j++)
            if (c[i][j] != c_ref[i][j]) errors++;
    return errors;
}

